def stats(nums: list[int]) -> dict[str, float | None]:
    if not nums:
        return {k: None for k in ('sum', 'product', 'mean', 'median', 'min', 'max')}
    total = sum(nums)
    prod = 1
    for n in nums:
        prod *= n
    mean = total / len(nums)
    sorted_nums = sorted(nums)
    mid = len(sorted_nums) // 2
    median = (sorted_nums[mid] + sorted_nums[~mid]) / 2
    return {
        'sum': float(total),
        'product': float(prod),
        'mean': mean,
        'median': median,
        'min': float(min(nums)),
        'max': float(max(nums))
    }

def stats(nums: list[int]) -> dict[str, int | float | None]:
    if not nums:
        return {k: None for k in ('sum', 'product', 'mean', 'median', 'min', 'max')}
    total = sum(nums)
    prod = 1
    for n in nums:
        prod *= n
    mean = total / len(nums)
    sorted_nums = sorted(nums)
    mid = len(sorted_nums) // 2
    if len(sorted_nums) % 2 == 0:
        median = (sorted_nums[mid - 1] + sorted_nums[mid]) / 2
    else:
        median = sorted_nums[mid]
    return {
        'sum': total,
        'product': prod,
        'mean': mean,
        'median': median,
        'min': min(nums),
        'max': max(nums)
    }

def filter_primes_desc(numbers):
    """Return a list of prime numbers from the input list, sorted in descending order."""
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    primes = [n for n in numbers if is_prime(n)]
    return sorted(primes, reverse=True)

